def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    recent = opp[-10:]
    recent_c = recent.count('C')
    total_c = opp.count('C')
    total_d = n - total_c

    # Count trailing defections by opponent
    tail_d = 0
    for a in reversed(opp):
        if a == 'D':
            tail_d += 1
        else:
            break

    # Count trailing mutual cooperation
    tail_cc = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'C' and opp[i] == 'C':
            tail_cc += 1
        else:
            break

    # Very early: cooperate to establish mutual cooperation
    if n <= 3:
        return 'C'

    # Opponent mostly defects: defect, but occasionally probe for recovery
    if total_d * 2 > n:
        if tail_d >= 3:
            return 'D'
        if total_d * 3 > n * 2:
            return 'D'
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Opponent just defected
    if last_opp == 'D':
        # If long cooperative history and single recent defection, forgive
        if tail_d == 1 and total_d <= 2:
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        # Retaliate
        if total_c * 3 > n * 2:
            return 'D'
        return 'D'

    # Opponent cooperated last
    # If we defected last and they still cooperated, don't over-exploit too early
    if last_me == 'D':
        if n > 85:
            return 'D'
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    # Late game exploitation against highly cooperative opponents
    if n > 90 and total_d == 0:
        return 'D'
    if n > 80 and total_d <= 2:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Against highly cooperative opponent, occasionally defect for extra points
    if total_d == 0:
        if n > 10 and n % 11 == 0:
            return 'D'
        return 'C'

    if total_d <= 2 and total_c > 15:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # Detect opponent shift toward defection
    if len(recent) >= 6:
        if recent_c <= 2 and total_c > recent_c:
            return 'D'

    # Mostly cooperate
    return 'C'
